<script setup>
import ActionNotice from './ActionNotice.vue'
import {ref,onMounted} from 'vue'
import {request} from './client'
const props=defineProps({control:Boolean})
const rows=ref([]),media=ref([]),error=ref(''),notice=ref(''),busy=ref(false),reason=ref(''),page=ref(0)
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){await run(async()=>{rows.value=await request(props.control?'commerce_events':'lecture_refunds','listing',{page:page.value},'GET');if(!props.control)media.value=await request('media_reconciliation','listing',{},'GET')})}
async function refund(row){if(!confirm('Request a full refund? Access is revoked only after provider confirmation.'))return;await run(async()=>{const r=await request('lecture_refunds','request',{order:row.name,reason:reason.value});notice.value=`Refund ${r.status}. ${r.message||''}`});await load()}
async function cleanup(row){if(!confirm('Remove all versions of this unused upload? Published or sold content cannot be removed here.'))return;await run(async()=>{const r=await request('media_reconciliation','cleanup',{name:row.name,reason:reason.value});notice.value=r.status});await load()}
onMounted(load)
</script>
<template><article class="panel"><ActionNotice :message="error||notice" :failure="!!error"/><h2>{{control?'Hosted website commerce reports':'Payments & unused uploads'}}</h2><p v-if="control">Signed tenant-reported metadata only. No student identity, course contents or cross-site database queries. Repeated lifecycle events are not additional revenue.</p><p v-if="busy" role="status">Loading…</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button class="button subtle"  :disabled="busy" @click="load">Refresh</button><label v-if="!control&&(rows.some(r=>r.status==='succeeded')||media.length)">Reason for this action<input v-model="reason" minlength="10" maxlength="500"></label><p v-if="!rows.length&&!busy">{{control?'No records available.':'No lesson payments to review. Class and programme payments are in Class fees.'}}</p><div v-if="rows.length" class="scroll"><table><thead><tr><th>Reference</th><th>Payment details</th><th>Status</th><th>Amount</th><th v-if="!control">Action</th></tr></thead><tbody><tr v-for="r in rows" :key="r.name||r.event_key"><td>{{r.receipt_number||r.reference_hash||r.name}}</td><td>{{r.purpose||'Lesson'}} {{r.tenant_id}}</td><td>{{r.status}} {{r.delivery_status}}</td><td>{{r.currency}} {{(r.amount_minor/100).toFixed(2)}}</td><td v-if="!control"><button v-if="!control&&r.status==='succeeded'" class="button subtle" :disabled="busy||reason.length<10" @click="refund(r)">Review refund</button></td></tr></tbody></table></div><template v-if="control&&(page||rows.length>=50)"><button class="button subtle" :disabled="page===0||busy" @click="page--;load()">Previous</button><button class="button subtle" :disabled="rows.length<50||busy" @click="page++;load()">Next</button></template><template v-else><h3>Unused uploads</h3><p>Review unfinished uploads that may be taking up space. Only uploads older than 24 hours can be cleaned up, after removal is confirmed. Published or sold content is protected.</p><p v-if="!media.length&&!busy" class="empty-state">You’re all caught up — no unfinished uploads need attention.</p><article v-for="m in media" :key="m.name"><p>{{m.name}} · {{m.media_state}} · {{m.bytes}} bytes · {{m.creation}}</p><button class="button subtle" :disabled="busy||reason.length<10" @click="cleanup(m)">Remove unused upload</button></article></template></article></template>

<style scoped>.panel{padding:24px}.panel p{line-height:1.7}.panel label{display:grid;gap:8px;margin:20px 0}.panel h3{margin-top:28px}.empty-state{padding:18px;background:var(--surface-alt,#f6f4ff);border-radius:12px}.scroll{overflow-x:auto}</style>
